/** By key ('PRESENCE.HELLO') or by class and kind as they appear in a header. */
export function findMessage(key: string): $.MessageInfo | undefined;
export function findMessage(cls: number, kind: number): $.MessageInfo | undefined;
export function findMessage(keyOrCls: string | number, kind?: number): $.MessageInfo | undefined {
  if (typeof keyOrCls === 'string') {
    return MESSAGES.find((m) => m.key === keyOrCls);
  }
  return MESSAGES.find((m) => m.cls === keyOrCls && (m.kind === null || m.kind === kind));
}

/** Encodes a message body from its JSON form: defaults applied, unknown keys and enum values rejected. */
export function encodeMessage(key: string, value: unknown = {}): $.Encoded {
  const m = findMessage(key);
  return m ? $.encodeJson(m.codec, value) : $.notFound(`message ${key}`);
}

/** Decodes a message body to its JSON form; an enum value the schema does not name is out_of_range. */
export function decodeMessage(key: string, bytes: Uint8Array): Decoded<Record<string, unknown>> {
  const m = findMessage(key);
  return m ? $.decodeJson(m.codec, bytes) : { ok: false, error: 'not_found' };
}
